def resolve(path, cwd, links):
    # Normalize the starting path
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]
    else:
        current = cwd
        components = path.split('/')

    link_count = 0

    i = 0
    while i < len(components):
        comp = components[i]

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            i += 1
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append the component
        if current == '/':
            new_path = '/' + comp
        else:
            new_path = current + '/' + comp

        # Check if this path is a symlink
        if new_path in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[new_path]

            # Parse the target and remaining components
            if target.startswith('/'):
                current = '/'
                target_components = target.split('/')[1:]
            else:
                # Target is relative to the directory containing the link
                if current == '/':
                    current = '/'
                else:
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                target_components = target.split('/')

            # Replace components with target components + remaining components
            remaining = components[i+1:]
            components = target_components + remaining
            i = 0
        else:
            current = new_path
            i += 1

    # Result has no trailing slash except for '/'
    return current

